static void JsonTlsLogIssuer(SCJsonBuilder *js, SSLState *ssl_state)
{
    if (ssl_state->server_connp.cert0_issuerdn) {
        if (ssl_state->server_connp.cert0_issuerdn_len == 0) {
            SCJbSetString(js, "issuerdn", "");
